from django.db import migrations, models


import unicodedata


def _sem_acento(texto):
    return "".join(c for c in unicodedata.normalize("NFD", texto.lower()) if unicodedata.category(c) != "Mn")


# Palavra no nome do serviço -> tipo (cor). A vet ajusta depois em Serviços.
PALAVRAS = [
    ("vacin", "vacinacao"), ("cirurg", "cirurgia"), ("castra", "cirurgia"), ("retorno", "retorno"),
    ("medica", "aplicacao_medicacao"), ("curativo", "curativo"), ("emergen", "emergencia"), ("urgen", "emergencia"),
    ("exame", "exame"), ("hemograma", "exame"), ("ultrass", "exame"), ("raio", "exame"),
    ("interna", "ambulatorial"), ("oxigen", "ambulatorial"), ("fluido", "ambulatorial"), ("consulta", "consulta"),
]


def tipo_pelo_nome(apps, schema_editor):
    Servico = apps.get_model("financeiro", "Servico")
    tipos = {}
    for s in Servico.objects.all():
        nome = _sem_acento(s.nome)
        s.tipo = next((t for palavra, t in PALAVRAS if palavra in nome), "")
        s.save(update_fields=["tipo"])
        tipos[str(s.pk)] = s.tipo
    # Agendamentos já feitos guardam o serviço em snapshot: grava o tipo lá também (cor na agenda).
    Agendamento = apps.get_model("agenda", "Agendamento")
    for a in Agendamento.objects.exclude(servicos=[]):
        servicos = [{**item, "tipo": tipos.get(str(item.get("id")), "")} for item in a.servicos]
        if servicos != a.servicos:
            a.servicos = servicos
            a.save(update_fields=["servicos"])


